"""Evasion rule: does a resistance profile defeat a given antibiotic? (issue #23)

For one drug and one ResistanceProfile the rule returns the ``evasion`` block of the
AntibioticCandidate contract (docs/contracts.md). It uses only what CARD records:

    unknown         the drug has no CARD drug class, so CARD cannot say either way
    unaffected      no gene in the profile is linked to the drug's class
    partly_affected a gene is linked to the drug's class, but CARD does not name this drug
    defeated        CARD names this drug for a gene in the profile (drug-level link)

Why ``partly_affected`` is the class-only case. CARD's class links on a gene are derived from
the specific drugs CARD lists for it, and CARD's drug-level lists are sparse: mecA is linked to
just methicillin and ceftaroline, yet its classes are all penicillins and cephalosporins. A drug
that shares the class but is not named is therefore *probably* affected, not *known* to be.
Collapsing the two would overstate what CARD says. Both rank below ``unaffected``.

"Unaffected" means no known link in CARD. It is not a measured result.
"""

from __future__ import annotations

import csv
from collections import defaultdict
from dataclasses import dataclass
from pathlib import Path
from typing import Mapping

STATUSES = ("unaffected", "unknown", "partly_affected", "defeated")
# Best first. `unknown` sits below `unaffected` (no information is not good news) and above
# `partly_affected` (a class link is evidence against the drug; silence is not).
EVASION_ORDER = {status: i for i, status in enumerate(STATUSES)}

DRUG_LINK = "confers_resistance_to_antibiotic"
NAMED_LIMIT = 5


@dataclass(frozen=True)
class Drug:
    """One approved antibiotic from the catalogue, with the CARD keys the rule joins on."""

    chembl_id: str
    name: str
    smiles: str | None
    inchikey: str | None
    class_aro_id: str | None  # CARD drug class; None when the catalogue could not map one
    class_name: str | None
    term_aro_id: str | None   # the drug's own CARD antibiotic term, when it has one
    class_route: str | None   # how the class was found: chembl_xref, name or atc_level4
    mechanism: str | None
    target: str | None
    max_phase: int
    first_approval: int | None


class DrugLinks:
    """CARD's drug-level links: for each determinant, the antibiotic terms it is listed against."""

    def __init__(self, links: Mapping[str, set[str]], names: Mapping[str, str], release: str):
        self._links = {gene: frozenset(drugs) for gene, drugs in links.items()}
        self._names = dict(names)
        self.release = release

    @classmethod
    def from_card(cls, release_dir: Path | str) -> "DrugLinks":
        release_dir = Path(release_dir)
        tables = release_dir / "tables"
        names = {r["aro_accession"]: r["name"] for r in _read(tables / "aro_terms.tsv")}
        links: dict[str, set[str]] = defaultdict(set)
        for r in _read(tables / "aro_relations.tsv"):
            if r["relation"] == DRUG_LINK:
                links[r["subject"]].add(r["object"])
        import json
        version = json.loads((release_dir / "manifest.json").read_text())["card_data_version"]
        return cls(links, names, f"card-{version}")

    def drugs_for(self, gene_aro_id: str) -> frozenset[str]:
        return self._links.get(gene_aro_id, frozenset())

    def name(self, aro_id: str) -> str:
        return self._names.get(aro_id, aro_id)


def _read(path: Path):
    with path.open(encoding="utf-8", newline="") as handle:
        yield from csv.DictReader(handle, delimiter="\t")


def _named(links: DrugLinks, gene: dict) -> str:
    names = sorted(links.name(a) for a in links.drugs_for(gene["aro_id"]))
    if not names:
        return "no individual drugs"
    shown = ", ".join(names[:NAMED_LIMIT])
    return shown if len(names) <= NAMED_LIMIT else f"{shown} and {len(names) - NAMED_LIMIT} more"


def _hits(genes: list[dict], mechanism_ids: set[str] | None = None) -> list[dict]:
    """One {gene_aro_id, mechanism_aro_id} per gene and mechanism, in profile order."""
    return [
        {"gene_aro_id": g["aro_id"], "mechanism_aro_id": m["aro_id"]}
        for g in genes for m in g["mechanisms"]
        if mechanism_ids is None or m["aro_id"] in mechanism_ids
    ]


def assess_evasion(profile: dict, drug: Drug, links: DrugLinks) -> dict:
    """The `evasion` block for one drug under one profile."""
    genes = profile["genes"]
    all_evidence = sorted({e for g in genes for e in g["evidence_ids"]}, key=_evidence_key)

    if drug.class_aro_id is None:
        return {
            "status": "unknown", "defeated_by": [], "profile_evidence_ids": all_evidence,
            "rationale": f"{drug.name.title()} has no CARD drug class in the catalogue, so CARD cannot say "
                         "whether any gene in the profile affects it.",
        }

    named = [g for g in genes if drug.term_aro_id and drug.term_aro_id in links.drugs_for(g["aro_id"])]
    by_class = [g for g in genes if any(c["aro_id"] == drug.class_aro_id for c in g["defeated_classes"])]

    if named:
        genes_hit, status = named, "defeated"
        rationale = "CARD lists {drug} for {genes}.".format(
            drug=drug.name.title(), genes=_join(g["name"] for g in named))
    elif by_class:
        genes_hit, status = by_class, "partly_affected"
        rationale = (
            "CARD links {genes} to {cls}, but names {named} rather than {drug}. {drug} shares the class, so "
            "it is probably affected; CARD does not say so directly."
        ).format(
            genes=_join(g["name"] for g in by_class), cls=drug.class_name,
            named="; ".join(f"{g['name']}: {_named(links, g)}" for g in by_class), drug=drug.name.title())
    else:
        return {
            "status": "unaffected", "defeated_by": [], "profile_evidence_ids": all_evidence,
            "rationale": f"No gene in the profile is linked to {drug.class_name} in CARD.",
        }

    return {
        "status": status,
        "defeated_by": _hits(genes_hit),
        "profile_evidence_ids": sorted({e for g in genes_hit for e in g["evidence_ids"]}, key=_evidence_key),
        "rationale": rationale,
    }


def _join(names) -> str:
    names = list(dict.fromkeys(names))
    return names[0] if len(names) == 1 else ", ".join(names[:-1]) + " and " + names[-1]


def _evidence_key(evidence_id: str) -> tuple[str, int]:
    return evidence_id[:1], int(evidence_id[1:])


def mechanisms_evaded(profile: dict, evasion: dict) -> list[str]:
    """Names of the profile's mechanisms that none of the drug's defeating genes use.

    For `unknown` this is empty: with no class, nothing can be said to be evaded.
    """
    if evasion["status"] == "unknown":
        return []
    used = {h["mechanism_aro_id"] for h in evasion["defeated_by"]}
    return [m["name"] for m in profile["mechanisms"] if m["aro_id"] not in used]

"""Resistance-aware ranking of approved antibiotics (WS4).

``rank_candidates`` takes a ResistanceProfile and a drug pool and returns one
AntibioticCandidate result (docs/contracts.md) plus a log of anything it could not rank.

The method is an ordered rule, not a blended score and not a learned model:

    1. evasion   unaffected, then unknown, then partly_affected, then defeated (evasion.py)
    2. activity  drugs with measured activity against the pathogen first, lower MIC first
    3. safety    drugs that pass the property rules, then drugs that fail them

Features stay separate on each candidate. A structural alert does not change the order, because
alerts such as the beta-lactam ring are normal in antibiotics. Drugs that tie on all three keys
are ordered alphabetically so the output is reproducible, and the explanation says so: that
order is not a finding.

Nothing here claims a drug works. "Unaffected" means CARD records no link between the profile's
genes and the drug's class.
"""

from __future__ import annotations

import hashlib
import uuid
from collections import Counter
from dataclasses import dataclass
from typing import Callable, Mapping, Sequence

from .evasion import EVASION_ORDER, Drug, DrugLinks, assess_evasion, mechanisms_evaded

METHOD = "ordered_rule_v0"
ORDER = ["evasion", "activity", "safety"]
RULE_SET = "antibiotic_relaxed"
PLACEHOLDER_RULE_SETS = {"antibiotic_relaxed"}  # limits not yet calibrated (issue #26)
CONTRACT_VERSION = "1"
SAFETY_ORDER = {"rules_passed": 0, "alerts_recorded": 0, "rules_failed": 1, "unavailable": 2}


@dataclass(frozen=True)
class Activity:
    """Measured activity of one drug against the profile's pathogen. Lower is better (a MIC)."""

    value: float
    unit: str       # e.g. "mg/L (median MIC)"
    statement: str  # the evidence sentence, naming the records it summarises


SmokeFn = Callable[[str], object]


def default_smoke(smiles: str):
    from htb_verify import check_molecule  # imported late: RDKit is heavy and only needed here
    return check_molecule(smiles, RULE_SET)


def _smoke_block(result) -> dict:
    d = result.descriptors
    return {
        "rule_set": result.rule_set,
        "valid": result.valid,
        "passed": result.passed,
        "strict_alerts": False,
        "descriptors": {
            "mw": round(d.mw, 2), "logp": round(d.logp, 2), "hbd": d.hbd, "hba": d.hba,
            "rot_bonds": d.rot_bonds, "psa": round(d.psa, 2), "heavy_atoms": d.heavy_atoms,
        },
        "violations": [
            {"rule": v.rule, "value": round(v.value, 2), "limit": round(v.limit, 2), "margin": round(v.margin, 2)}
            for v in result.violations
        ],
        "alerts": list(result.alerts),
        "sa_score": result.sa_score,
    }


def _feature(value=None, unit=None, evidence_ids: Sequence[str] = ()) -> dict:
    available = value is not None
    return {"available": available, "value": value, "unit": unit if available else None,
            "evidence_ids": list(evidence_ids) if available else []}


def _safety_value(smoke: dict) -> str:
    if not smoke["passed"]:
        return "rules_failed"
    return "alerts_recorded" if smoke["alerts"] else "rules_passed"


def _sort_key(c: dict) -> tuple:
    act = c["features"]["activity"]
    return (
        EVASION_ORDER[c["evasion"]["status"]],
        (0, act["value"]) if act["available"] else (1, 0.0),
        SAFETY_ORDER[c["features"]["safety"]["value"]],
    )


def _candidate(profile: dict, drug: Drug, links: DrugLinks, smoke: dict, activity: Activity | None) -> dict:
    evidence = [{
        "id": "E1", "kind": "smoke_test", "source": "htb_verify", "release": smoke["rule_set"],
        "source_id": drug.chembl_id,
        "statement": "Property rules and structural alerts from the Python smoke test.",
    }]
    if drug.class_aro_id:
        evidence.append({
            "id": f"E{len(evidence) + 1}", "kind": "drug_class", "source": "htb_resistance",
            "release": "catalogue", "source_id": drug.chembl_id,
            "statement": f"Mapped to CARD class {drug.class_name} ({drug.class_aro_id}) by {drug.class_route}.",
        })
    activity_ids = []
    if activity:
        activity_ids = [f"E{len(evidence) + 1}"]
        evidence.append({
            "id": activity_ids[0], "kind": "activity", "source": "chembl", "release": "chembl",
            "source_id": drug.chembl_id, "statement": activity.statement,
        })

    evasion = assess_evasion(profile, drug, links)
    return {
        "candidate_id": drug.chembl_id,
        "name": drug.name,
        "source": "approved",
        "smiles": drug.smiles,
        "inchikey": drug.inchikey,
        "drug_class": {"aro_id": drug.class_aro_id, "name": drug.class_name} if drug.class_aro_id else None,
        "mechanism_of_action": drug.mechanism,
        "target": {"name": drug.target, "gene_aro_ids": []} if drug.target else None,
        "rank": None,
        "evasion": evasion,
        "features": {
            "activity": _feature(activity.value if activity else None, activity.unit if activity else None, activity_ids),
            "target_hit": _feature(),
            "docking": _feature(),
            "safety": _feature(_safety_value(smoke), None, ["E1"]),
        },
        "explanation": {"summary": "", "mechanisms_evaded": mechanisms_evaded(profile, evasion),
                        "missing": [], "caveats": []},
        "smoke_test": smoke,
        "certificate_status": "not_run",
        "certificate": None,
        "generated": None,
        "evidence": evidence,
    }


def _genes(profile: dict, evasion: dict) -> str:
    names = {g["aro_id"]: g["name"] for g in profile["genes"]}
    return ", ".join(dict.fromkeys(names[h["gene_aro_id"]] for h in evasion["defeated_by"]))


def _explain(profile: dict, c: dict, rank: int, total: int, tied_with: int, route: str | None) -> dict:
    ev, feats, smoke = c["evasion"], c["features"], c["smoke_test"]
    cls = c["drug_class"]["name"] if c["drug_class"] else None
    parts = [f"Ranked {rank} of {total}."]
    if ev["status"] == "unaffected":
        parts.append(f"Its class ({cls}) is not linked to any gene in the profile in CARD.")
    elif ev["status"] == "unknown":
        parts.append("It has no CARD drug class, so evasion could not be assessed.")
    elif ev["status"] == "partly_affected":
        parts.append(f"CARD links its class ({cls}) to {_genes(profile, ev)} but does not name this drug.")
    else:
        parts.append(f"CARD lists this drug against {_genes(profile, ev)}.")
    if feats["activity"]["available"]:
        parts.append(f"Activity: {feats['activity']['value']} {feats['activity']['unit']}.")
    if not smoke["passed"]:
        failed = ", ".join(v["rule"] for v in smoke["violations"])
        parts.append(f"It fails the property rules ({failed}), which ranks it below drugs that pass.")
    if tied_with:
        parts.append(f"It ties with {tied_with} other drug{'s' if tied_with != 1 else ''} on every ranking "
                     "feature; the order within the tie is alphabetical and is not a finding.")

    missing = []
    if not feats["activity"]["available"]:
        missing.append("No activity data against this pathogen.")
    missing += ["No target-hit evidence.", "No docking result."]
    if not cls:
        missing.append("No CARD drug class.")
    elif route == "atc_level4":
        missing.append("Drug class inferred from its ATC group, not from a CARD cross-reference or name.")

    caveats = []
    if ev["status"] in ("unaffected", "unknown"):
        caveats.append("Evasion here means no known link in CARD. It is not a measured result.")
    elif ev["status"] == "partly_affected":
        caveats.append("A class-level link is weaker evidence than a drug-level one; the drug may still work.")
    if smoke["rule_set"] in PLACEHOLDER_RULE_SETS:
        caveats.append(f"The {smoke['rule_set']} limits are placeholders until they are calibrated.")
    if smoke["alerts"]:
        caveats.append("Structural alerts are recorded but do not change the rank; reactive groups are "
                       "normal in antibiotics.")
    return {"summary": " ".join(parts), "mechanisms_evaded": c["explanation"]["mechanisms_evaded"],
